import React from 'react';

import clsx from 'clsx';
import * as L from 'leaflet';

import { getDefaultTileLayer, getLayersControl, getMap } from '@helpers/leafletHelper';

import styles from './styles.module.less';

interface IMapPointProps extends React.HTMLAttributes<HTMLDivElement> {
  point: [number, number];
  mapType?: {
    tileUrlTmpl: string;
  };
  height?: number;
}

const MapPoint: React.FC<IMapPointProps> = ({ point, height = 300, mapType, ...anotherProps }) => {
  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(undefined);
  React.useEffect(() => {
    if (!ref.current) return;

    const map = getMap(ref.current, { preferCanvas: true });

    getDefaultTileLayer().addTo(map);
    getLayersControl().addTo(map);

    mapRef.current = map;
  }, []);

  React.useEffect(() => {
    if (!mapRef.current) {
      return;
    }

    const icon = L.divIcon({
      className: 'bg-none border-none',
      html: `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 16 16"><path fill="red" d="M1.5 1a.5.5 0 0 0-.5.5v4a.5.5 0 0 1-1 0v-4A1.5 1.5 0 0 1 1.5 0h4a.5.5 0 0 1 0 1h-4ZM10 .5a.5.5 0 0 1 .5-.5h4A1.5 1.5 0 0 1 16 1.5v4a.5.5 0 0 1-1 0v-4a.5.5 0 0 0-.5-.5h-4a.5.5 0 0 1-.5-.5ZM.5 10a.5.5 0 0 1 .5.5v4a.5.5 0 0 0 .5.5h4a.5.5 0 0 1 0 1h-4A1.5 1.5 0 0 1 0 14.5v-4a.5.5 0 0 1 .5-.5Zm15 0a.5.5 0 0 1 .5.5v4a1.5 1.5 0 0 1-1.5 1.5h-4a.5.5 0 0 1 0-1h4a.5.5 0 0 0 .5-.5v-4a.5.5 0 0 1 .5-.5Z"></path></svg>`,
      iconSize: [24, 24],
      iconAnchor: [12, 12],
    });
    const marker = new L.Marker(point, { icon });

    marker.addTo(mapRef.current);
    mapRef.current.setView(point, 14);
  }, [point]);

  return (
    <div
      ref={ref}
      {...anotherProps}
      className={clsx(anotherProps?.className, styles.mapEle)}
      style={{ height: height, ...(anotherProps?.style || {}) }}
    />
  );
};

export default MapPoint;
